/** Closes a suite's own sockets, then stops each of its servers once they have seen their sockets close. */
export async function closeTracked(clientList: WebSocket[], serverList: HalServer[]): Promise<void> {
  for (const client of clientList.splice(0)) client.terminate();
  for (const hal of serverList.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

